import CartographAnalysis
import CartographCore
import Testing

@Suite("생성 마커는 실제 앞부분의 일반 주석만 근거로 쓴다")
struct GeneratedSourceMarkerTests {
    @Test("명시적인 생성 헤더는 원문과 줄 번호를 보존한다", arguments: [
        "// @generated", "// Generated by Needle 1.0", "// Generated using Sourcery 2.0",
        "// This file was generated by SwiftGen.", "// This file is generated by ExampleGenerator."
    ])
    func observedHeader(marker: String) {
        let result = GeneratedSourceMarker.inspect(prefix: "\u{FEFF}// Copyright\r\n\r\n\(marker)\r\nstruct A {}",
            hasMoreBytes: false)
        #expect(result.status == .markerObserved)
        #expect(result.evidence == .init(line: 3, text: marker))
        #expect(result.suggestion?.contains("changes no findings") == true)
    }

    @Test("파일명 추정 없이 코드나 인용 또는 손으로 관리한다는 주석을 생성으로 판정하지 않는다", arguments: [
        "// Human-managed design tokens\nstruct Token {}",
        "// Generated by hand\nstruct Token {}",
        "// Generated by humans\nstruct Token {}",
        "// Generated by \nstruct Token {}",
        "// Generated by !!!\nstruct Token {}",
        "// Example: Generated by Needle\nstruct Token {}",
        "// \"@generated\"\nstruct Token {}",
        "let example = \"// Generated by Needle\"",
        "import Foundation\n// @generated",
        "struct A {} // @generated", "", "// @generatedly"
    ])
    func negativeControls(source: String) {
        let result = GeneratedSourceMarker.inspect(prefix: source, hasMoreBytes: false)
        #expect(result.status == .noMarkerInHeader)
        #expect(result.evidence == nil)
        #expect(result.suggestion == nil)
    }

    @Test("잘린 마지막 줄을 완성된 마커로 받아들이지 않는다")
    func truncatedAndCompleteLine() {
        #expect(GeneratedSourceMarker.inspect(prefix: "// @generated", hasMoreBytes: true).status == .prefixLimit)
        #expect(GeneratedSourceMarker.inspect(prefix: "// @generated\n", hasMoreBytes: true).status == .markerObserved)
        #expect(GeneratedSourceMarker.inspect(prefix: "// normal\n", hasMoreBytes: true).status == .prefixLimit)
        #expect(GeneratedSourceMarker.inspect(prefix: "// normal\r// @generated\r", hasMoreBytes: false)
            .evidence?.line == 2)
    }

    @Test("문서와 블록 주석 또는 너무 긴 헤더는 미지원으로 남긴다", arguments: [
        "/// @generated", "//! @generated", "/* @generated */", "// " + String(repeating: "x", count: 600)
    ])
    func unsupportedHeaders(source: String) {
        let result = GeneratedSourceMarker.inspect(prefix: source, hasMoreBytes: false)
        #expect(result.status == .unsupportedHeader)
        #expect(result.evidence == nil)
    }
}
